import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`flooring-estimate`,heroTitle:`Generate flooring estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded plans and finish schedules, sizes flooring materials and labor, and drafts a detailed estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your flooring scope`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded flooring plans, finish schedules, or site notes. Build a complete flooring estimate. (1) Extract room areas, material types, patterns, transitions, subfloor prep needs, demolition scope, and installation constraints from the uploaded files. (2) Estimate materials, underlayment, trim, labor, moisture mitigation, and equipment needs. (3) Build pricing options with assumptions, alternates, and margin. (4) Highlight exclusions, field-verification items, and schedule dependencies that should be confirmed before sending. (5) Deliver a detailed flooring estimate with line-item pricing, scope summary, and next steps that is ready for the customer.`,heroOverlaySteps:[`Extracting room areas, finish types, prep work, and transitions from your files`,`Sizing materials, underlayment, labor, and equipment needs`,`Building pricing options with assumptions, alternates, and margin`,`Customer-ready flooring estimate with scope summary, ready to send`],generatingSteps:[`Reading the uploaded plans, finish schedules, and site notes`,`Designing an agent to organize takeoffs, prep requirements, and labor assumptions`,`Configuring estimate logic for alternates, exclusions, and margin`,`Preparing a detailed flooring estimate with line items and next steps`],featureSectionTitle:`From finish schedule to installation-ready estimate`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built around material and prep reality`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, takeoffs, and internal planning workflows stay connected so estimates and revisions move faster.`,`Room counts. Prep assumptions. Material takeoffs. Labor. Computer gives your team a flooring estimate draft that is ready for customer review.`],capabilitySectionTitle:`Your estimator, on autopilot`,capabilitySectionSubtitle:`Upload the scope, get back a flooring estimate built around the real install conditions.`,capabilityCards:[{title:`Scope Extraction`,description:`Computer can extract room areas, finish types, demolition scope, prep needs, and transition details from plans, schedules, and notes.`},{title:`Materials & Labor Planning`,description:`Computer can size flooring, underlayment, trim, moisture mitigation, and labor hours so the estimate reflects the actual project.`},{title:`Pricing Options`,description:`Computer can turn the scope into pricing with assumptions, alternates, and margin so your team can move faster from takeoff to quote.`},{title:`Connect Your Tools`,description:`Computer can organize estimate drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred vendors, markup rules, and estimate structure across sessions so every quote stays consistent.`},{title:`Revision Support`,description:`Computer can update the estimate when room counts, finish selections, or prep assumptions change after the first draft.`}]});export{t as default};
